/*
Three-valued logic:
values: 0=false, 1=unknown, 2=true

Negation:
-0 = 2
-1 = 1
-2 = 0

Conjunction = min
Disjunction = max
*/

typedef struct {
    int cnt[3]; /* number of assignments making expression evaluate to 0,1,2 */
} Node;

static Node make_const(int v) {
    Node x = {{0,0,0}};
    x.cnt[v] = 27; /* all assignments */
    return x;
}

static Node make_var(char c) {
    Node x = {{0,0,0}};
    /* For one variable among P,Q,R:
       each value occurs with the other two variables arbitrary => 3*3 = 9 times */
    x.cnt[0] = x.cnt[1] = x.cnt[2] = 9;
    return x;
}

static Node negate_node(Node a) {
    Node r;
    r.cnt[0] = a.cnt[2];
    r.cnt[1] = a.cnt[1];
    r.cnt[2] = a.cnt[0];
    return r;
}

static Node combine_and(Node a, Node b) {
    Node r = {{0,0,0}};
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) {
            int v = (i < j) ? i : j; /* min */
            r.cnt[v] += a.cnt[i] * b.cnt[j] / 27;
        }
    }
    return r;
}

static Node combine_or(Node a, Node b) {
    Node r = {{0,0,0}};
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) {
            int v = (i > j) ? i : j; /* max */
            r.cnt[v] += a.cnt[i] * b.cnt[j] / 27;
        }
    }
    return r;
}

/*
To correctly count assignments, for each expression we track exact truth table
over all 27 assignments, encoded directly.
This avoids dependency issues between subexpressions.
*/
typedef struct {
    unsigned char val[27];
} Expr;

static int getP(int m) { return m / 9; }
static int getQ(int m) { return (m / 3) % 3; }
static int getR(int m) { return m % 3; }

static Expr parse_expr();

static Expr make_const_expr(int v) {
    Expr e;
    for (int i = 0; i < 27; i++) e.val[i] = (unsigned char)v;
    return e;
}

static Expr make_var_expr(char c) {
    Expr e;
    for (int i = 0; i < 27; i++) {
        if (c == 'P') e.val[i] = (unsigned char)getP(i);
        else if (c == 'Q') e.val[i] = (unsigned char)getQ(i);
        else e.val[i] = (unsigned char)getR(i);
    }
    return e;
}

static Expr negate_expr(Expr a) {
    Expr r;
    for (int i = 0; i < 27; i++) r.val[i] = 2 - a.val[i];
    return r;
}

static Expr and_expr(Expr a, Expr b) {
    Expr r;
    for (int i = 0; i < 27; i++) r.val[i] = (a.val[i] < b.val[i]) ? a.val[i] : b.val[i];
    return r;
}

static Expr or_expr(Expr a, Expr b) {
    Expr r;
    for (int i = 0; i < 27; i++) r.val[i] = (a.val[i] > b.val[i]) ? a.val[i] : b.val[i];
    return r;
}

static Expr parse_factor() {
    if (s[pos] == '-') {
        pos++;
        Expr t = parse_factor();
        return negate_expr(t);
    } else if (s[pos] == '(') {
        pos++;
        Expr t = parse_expr();
        if (s[pos] == ')') pos++;
        return t;
    } else if (s[pos] == '0' || s[pos] == '1' || s[pos] == '2') {
        int v = s[pos++] - '0';
        return make_const_expr(v);
    } else {
        char c = s[pos++];
        return make_var_expr(c);
    }
}

static Expr parse_term() {
    Expr left = parse_factor();
    while (s[pos] == '*') {
        pos++;
        Expr right = parse_factor();
        left = and_expr(left, right);
    }
    return left;
}

static Expr parse_expr() {
    Expr left = parse_term();
    while (s[pos] == '+') {
        pos++;
        Expr right = parse_term();
        left = or_expr(left, right);
    }
    return left;
}

