// Three-valued logic operations
int neg(int a) {
    return 2 - a;
}

int conj(int a, int b) {
    return min(a, b);
}

int disj(int a, int b) {
    return max(a, b);
}

// Tokenize the expression into postfix (Reverse Polish Notation)
vector<string> toPostfix(const string& expr) {
    vector<string> output;
    stack<char> ops;
    map<char, int> prec;
    prec['-'] = 3;
    prec['*'] = 2;
    prec['+'] = 1;

    for (size_t i = 0; i < expr.size(); ++i) {
        char c = expr[i];
        if (c == '0' || c == '1' || c == '2' || c == 'P' || c == 'Q' || c == 'R') {
            output.push_back(string(1, c));
        } else if (c == '(') {
            ops.push(c);
        } else if (c == ')') {
            while (!ops.empty() && ops.top() != '(') {
                output.push_back(string(1, ops.top()));
                ops.pop();
            }
            if (!ops.empty()) ops.pop(); // remove '('
        } else if (c == '-' || c == '*' || c == '+') {
            while (!ops.empty() && ops.top() != '(' && prec[ops.top()] >= prec[c]) {
                output.push_back(string(1, ops.top()));
                ops.pop();
            }
            ops.push(c);
        }
    }
    while (!ops.empty()) {
        output.push_back(string(1, ops.top()));
        ops.pop();
    }
    return output;
}

// Evaluate postfix expression given variable assignments
int evaluate(const vector<string>& postfix, int p, int q, int r) {
    stack<int> st;
    for (const string& token : postfix) {
        if (token == "0") st.push(0);
        else if (token == "1") st.push(1);
        else if (token == "2") st.push(2);
        else if (token == "P") st.push(p);
        else if (token == "Q") st.push(q);
        else if (token == "R") st.push(r);
        else if (token == "-") {
            int a = st.top(); st.pop();
            st.push(neg(a));
        } else if (token == "*") {
            int b = st.top(); st.pop();
            int a = st.top(); st.pop();
            st.push(conj(a, b));
        } else if (token == "+") {
            int b = st.top(); st.pop();
            int a = st.top(); st.pop();
            st.push(disj(a, b));
        }
    }
    return st.top();
}

