    char val; // for variables/constants: 'P','Q','R','0','1','2'
    int l = -1, r = -1;
};

string s;
int posi;
vector<Node> nodes;

int newNode(const Node& n) {
    nodes.push_back(n);
    return (int)nodes.size() - 1;
}

// Grammar:
// expr := term { + term }
// term := factor { * factor }
// factor := - factor | ( expr ) | atom
// atom := P | Q | R | 0 | 1 | 2

int parseExpr();

int parseFactor() {
    if (s[posi] == '-') {
        posi++;
        int child = parseFactor();
        Node n;
        n.op = '-';
        n.l = child;
        return newNode(n);
    }
    if (s[posi] == '(') {
        posi++;
        int inside = parseExpr();
        posi++; // ')'
        return inside;
    }
    Node n;
    n.op = 'v';
    n.val = s[posi++];
    return newNode(n);
}

int parseTerm() {
    int left = parseFactor();
    while (posi < (int)s.size() && s[posi] == '*') {
        posi++;
        int right = parseFactor();
        Node n;
        n.op = '*';
        n.l = left;
        n.r = right;
        left = newNode(n);
    }
    return left;
}

int parseExpr() {
    int left = parseTerm();
    while (posi < (int)s.size() && s[posi] == '+') {
        posi++;
        int right = parseTerm();
        Node n;
        n.op = '+';
        n.l = left;
        n.r = right;
        left = newNode(n);
    }
    return left;
}

// 3-valued logic:
// neg: 0->2, 1->1, 2->0
// and: min
// or : max

int evalNode(int u, int P, int Q, int R) {
    const Node& n = nodes[u];
    if (n.op == 'v') {
        if (n.val == 'P') return P;
        if (n.val == 'Q') return Q;
        if (n.val == 'R') return R;
        return n.val - '0';
    }
    if (n.op == '-') {
        int x = evalNode(n.l, P, Q, R);
        return 2 - x;
    }
    if (n.op == '*') {
        int a = evalNode(n.l, P, Q, R);
        int b = evalNode(n.r, P, Q, R);
        return min(a, b);
    }
    int a = evalNode(n.l, P, Q, R);
    int b = evalNode(n.r, P, Q, R);
    return max(a, b);
}

