public class ThreeValuedLogic {
    static class Node {
        char type; // 'v' for variable, 'o' for operator
        char var;  // 'P','Q','R' for variable nodes
        char op;   // '-', '*', '+' for operator nodes
        Node left, right; // left for unary '-', both for binary
    }

    static int pos;
    static String s;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextLine()) {
            String line = sc.nextLine().trim();
            if (line.equals(".")) break;
            s = line;
            pos = 0;
            Node expr = parseExpr();
            int count = 0;
            for (int p = 0; p < 3; p++) {
                for (int q = 0; q < 3; q++) {
                    for (int r = 0; r < 3; r++) {
                        Map<Character, Integer> vars = new HashMap<>();
                        vars.put('P', p);
                        vars.put('Q', q);
                        vars.put('R', r);
                        if (evaluate(expr, vars) == 2) count++;
                    }
                }
            }
            System.out.println(count);
        }
        sc.close();
    }

    static Node parseExpr() {
        return parseDisj();
    }

    static Node parseDisj() {
        Node left = parseConj();
        while (pos < s.length() && s.charAt(pos) == '+') {
            pos++;
            Node right = parseConj();
            Node op = new Node();
            op.type = 'o';
            op.op = '+';
            op.left = left;
            op.right = right;
            left = op;
        }
        return left;
    }

    static Node parseConj() {
        Node left = parseUnary();
        while (pos < s.length() && s.charAt(pos) == '*') {
            pos++;
            Node right = parseUnary();
            Node op = new Node();
            op.type = 'o';
            op.op = '*';
            op.left = left;
            op.right = right;
            left = op;
        }
        return left;
    }

    static Node parseUnary() {
        if (pos < s.length() && s.charAt(pos) == '-') {
            pos++;
            Node child = parseUnary();
            Node op = new Node();
            op.type = 'o';
            op.op = '-';
            op.left = child;
            return op;
        }
        if (pos < s.length() && s.charAt(pos) == '(') {
            pos++; // '('
            Node inner = parseExpr();
            pos++; // ')'
            return inner;
        }
        // variable
        Node varNode = new Node();
        varNode.type = 'v';
        varNode.var = s.charAt(pos);
        pos++;
        return varNode;
    }

    static int evaluate(Node node, Map<Character, Integer> vars) {
        if (node.type == 'v') {
            return vars.get(node.var);
        }
        if (node.op == '-') {
            int val = evaluate(node.left, vars);
            return (2 - val); // 0->2, 1->1, 2->0
        }
        int leftVal = evaluate(node.left, vars);
        int rightVal = evaluate(node.right, vars);
        if (node.op == '*') {
            return Math.min(leftVal, rightVal);
        } else { // '+'
            return Math.max(leftVal, rightVal);
        }
    }
}

