        int expr() {
            int res = term();
            while (pos < n && s[pos] == '+') {
                pos++;
                int rhs = term();
                res = Math.max(res, rhs);
            }
            return res;
        }

        // term := factor { '*' factor }
        int term() {
            int res = factor();
            while (pos < n && s[pos] == '*') {
                pos++;
                int rhs = factor();
                res = Math.min(res, rhs);
            }
            return res;
        }

        // factor := '-' factor | '(' expr ')' | constant | variable
        int factor() {
            char c = s[pos];
            if (c == '-') {
                pos++;
                return 2 - factor();
            } else if (c == '(') {
                pos++;
                int res = expr();
                pos++; // ')'
                return res;
            } else if (c == '0' || c == '1' || c == '2') {
                pos++;
                return c - '0';
