import sys

def evaluate(expr, vals):
    # Replace variables with their values
    expr = expr.replace('P', str(vals['P']))
    expr = expr.replace('Q', str(vals['Q']))
    expr = expr.replace('R', str(vals['R']))

    # We'll convert to postfix and evaluate
    # Operator precedence: - (unary) highest, then *, then +
    def apply_op(op, b, a=None):
        if op == '-':
            return 2 - b  # negation in three-valued logic
        elif op == '*':
            return min(a, b)
        elif op == '+':
            return max(a, b)

    precedence = {'-': 3, '*': 2, '+': 1}
    output = []
    ops = []
    i = 0
    while i < len(expr):
        ch = expr[i]
        if ch.isdigit():
            output.append(int(ch))
        elif ch == '(':
            ops.append(ch)
        elif ch == ')':
            while ops and ops[-1] != '(':
                output.append(ops.pop())
            ops.pop()  # remove '('
        elif ch in '+-*':
            # unary minus detection: if previous token was operator or '(' or start
            if ch == '-':
                if i == 0 or expr[i-1] in '(*+-':
                    # treat as unary
                    ops.append(ch)
                    i += 1
                    continue
            while ops and ops[-1] != '(' and precedence.get(ops[-1], 0) >= precedence[ch]:
                output.append(ops.pop())
            ops.append(ch)
        i += 1
    while ops:
        output.append(ops.pop())

    # Evaluate postfix
    stack = []
    for token in output:
        if isinstance(token, int):
            stack.append(token)
        elif token == '-':
            stack.append(apply_op('-', stack.pop()))
        else:
            b = stack.pop()
            a = stack.pop()
            stack.append(apply_op(token, b, a))
    return stack[0]

