        return val

    def expr(self):
        # expr := term { + term }
        val = self.term()
        while self.i < self.n and self.s[self.i] == '+':
            self.i += 1
            val = max(val, self.term())
        return val

    def term(self):
        # term := factor { * factor }
        val = self.factor()
        while self.i < self.n and self.s[self.i] == '*':
            self.i += 1
            val = min(val, self.factor())
        return val

    def factor(self):
        # factor := -factor | (expr) | constant | variable
        c = self.s[self.i]
        if c == '-':
            self.i += 1
            return 2 - self.factor()
        elif c == '(':
            self.i += 1
            val = self.expr()
            self.i += 1  # skip ')'
            return val
        elif c in '012':
            self.i += 1
            return ord(c) - ord('0')
        else:  # P, Q, R
            self.i += 1
            return self.env[c]

def evaluate(formula, p, q, r):
    env = {'P': p, 'Q': q, 'R': r}
    return Parser(formula, env).parse()

def main():
    out = []
    for line in sys.stdin:
        s = line.strip()
        if not s:
            continue
        if s == '.':
            break
        cnt = 0
        for p in range(3):
            for q in range(3):
                for r in range(3):
                    if evaluate(s, p, q, r) == 2:
                        cnt += 1
        out.append(str(cnt))
    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()
